`timescale 1ns/1ps
// Exact finite-domain vectors are generated by the archived software integer
// reference, not by host floats. Excludes unsupported NaN/Inf/overflow.
module fp32_math_boundary_tb;
  import fp32_math_pkg::*;
  string vector_file;
  integer fd, rc, count=0;
  logic [31:0] a, b, expected_add, expected_mul, actual;
  initial begin
    vector_file="handoff/pe_special_validation_2026-10-20/fp32_boundary_vectors.txt";
    if ($value$plusargs("VECTORS=%s",vector_file)) begin end
    fd=$fopen(vector_file,"r");
    if (!fd) $fatal(1,"run Run-PeSpecialValidation.py to create boundary vectors");
    while (!$feof(fd)) begin
      rc=$fscanf(fd,"%h %h %h %h\n",a,b,expected_add,expected_mul);
      if (rc!=4) $fatal(1,"malformed boundary vector %0d",count);
      actual=fp32_add(a,b);
      if (actual!==expected_add)
        $fatal(1,"boundary add index=%0d a=%08x b=%08x got=%08x expected=%08x",count,a,b,actual,expected_add);
      actual=fp32_mul(a,b);
      if (actual!==expected_mul)
        $fatal(1,"boundary mul index=%0d a=%08x b=%08x got=%08x expected=%08x",count,a,b,actual,expected_mul);
      count=count+1;
    end
    $fclose(fd);
    if (count<20000) $fatal(1,"insufficient boundary vectors");
    $display("fp32_math_boundary_tb PASS exact_finite_pairs=%0d add_and_mul_checked=1",count);
    $finish;
  end
endmodule
